import type { ReconnectionState } from "./session-coordinator.js";

export interface Workspace {
  id: string;
}

export class WorkspaceRuntime {
  constructor(
    readonly workspace: Workspace,
    private readonly reconnectionState: ReconnectionState,
  ) {}

  reconnect(): string | undefined {
    return this.reconnectionState.resumeToken;
  }

  dispose(): void {
    // Workspace-scoped resources are released when the active workspace changes.
  }
}

import assert from "node:assert/strict";
import test from "node:test";

import { SessionCoordinator } from "../src/session-coordinator.js";

test("reconnection state survives workspace replacement", () => {
  const coordinator = new SessionCoordinator({ id: "workspace-a" });
  coordinator.updateReconnectionState("resume-token", 42);

  coordinator.replaceWorkspace({ id: "workspace-b" });

  assert.equal(coordinator.reconnect(), "resume-token");
});

import { WorkspaceRuntime, type Workspace } from "./workspace-runtime.js";

export interface ReconnectionState {
  resumeToken?: string;
  lastAcknowledgedSequence: number;
}

export class SessionCoordinator {
  private readonly reconnectionState: ReconnectionState = {
    lastAcknowledgedSequence: 0,
  };

  private runtime: WorkspaceRuntime;

  constructor(workspace: Workspace) {
    this.runtime = new WorkspaceRuntime(workspace, this.reconnectionState);
  }

  replaceWorkspace(workspace: Workspace): void {
    this.runtime.dispose();
    this.runtime = new WorkspaceRuntime(workspace, this.reconnectionState);
  }

  reconnect(): string | undefined {
    return this.runtime.reconnect();
  }

  updateReconnectionState(resumeToken: string, sequence: number): void {
    this.reconnectionState.resumeToken = resumeToken;
    this.reconnectionState.lastAcknowledgedSequence = sequence;
  }
}

